installer-script.script:

function installation_check() {
    // Vérification version macOS minimum
    if (system.compareVersions(system.version.ProductVersion, '12.0') < 0) {
        my.result.title = 'Version macOS incompatible';
        my.result.message = 'Home Assistant Desktop nécessite macOS 12.0 ou supérieur.';
        my.result.type = 'Fatal';
        return false;
    }

    // Vérification architecture
    var arch = system.hardware.architecture;
    if (arch != 'x86_64' && arch != 'arm64') {
        my.result.title = 'Architecture non supportée';
        my.result.message = 'Home Assistant Desktop supporte uniquement Intel x86_64 et Apple Silicon.';
        my.result.type = 'Fatal';
        return false;
    }

    // Vérification espace disque
    var freeSpace = system.files.freeSpace('/');
    if (freeSpace < 2147483648) { /* 2GB */
        my.result.title = 'Espace disque insuffisant';
        my.result.message = 'Home Assistant Desktop nécessite au moins 2GB d\'espace libre.';
        my.result.type = 'Fatal';
        return false;
    }

    return true;
}


function volume_check(volume) {
    // Vérification que l'installation se fait sur le volume système
    if (volume.mountpoint != '/') {
        my.result.title = 'Volume incorrect';
        my.result.message = 'Home Assistant Desktop doit être installé sur le volume système.';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
